INSERT INTO feature VALUES('module-nesting','modules','Nested modules and paths','modules','implemented','ordinary',NULL,'Modules declared inside modules and reached by dotted paths, with signature matching across them. A dotted declaration name, `theory Kit.Labelled` or `module Kit.Tools`, declares in the modules its prefix names, each opened where the source declares no module of that name and exported once a declaration made through it is; `Model(Kit.Labelled)` reads a theory by its path, and the prelude declares `Gandr.Package` so. A prefix may run any depth, `Deep.Mid.Low.Shape`, and a module block may sit in a dotted module and read into it and back out; a dotted name is read at a top-level form alone, so one inside a module block is refused.','surface-lowering surface-grammar surface-format surface-lsp','corpus/model/modules/module-nesting-and-paths.gandr corpus/model/modules/dotted-names.gandr corpus/pathological/modules/dotted-prefix-clash.gandr corpus/model/modules/dotted-deep.gandr corpus/model/modules/dotted-nested.gandr corpus/pending/pathological/modules/dotted-in-nested.gandr','corpus/model/modules/module-nesting-and-paths.gandr',NULL);
